// Lokale Datums-Helfer. Bewusst lokal statt UTC, damit „heute“ für
// den Nutzer bedeutet, was sein Kalender bedeutet (auch über Zeitzonenwechsel).

export const WEEKDAYS_SHORT = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'] as const

export const WEEKDAYS = [
  'Sonntag',
  'Montag',
  'Dienstag',
  'Mittwoch',
  'Donnerstag',
  'Freitag',
  'Samstag',
] as const

export const MONTHS = [
  'Januar',
  'Februar',
  'März',
  'April',
  'Mai',
  'Juni',
  'Juli',
  'August',
  'September',
  'Oktober',
  'November',
  'Dezember',
] as const

/** Kalendertag als „JJJJ-MM-TT“ (lokal). */
export function dayKey(date: Date): string {
  const y = date.getFullYear()
  const m = String(date.getMonth() + 1).padStart(2, '0')
  const d = String(date.getDate()).padStart(2, '0')
  return `${y}-${m}-${d}`
}

/** „JJJJ-MM-TT“ als lokaler Kalender-Mitternachtspunkt. */
export function parseDayKey(key: string): Date {
  return new Date(`${key}T00:00:00`)
}

export function addDays(date: Date, days: number): Date {
  const copy = new Date(date)
  copy.setDate(copy.getDate() + days)
  return copy
}

export function todayKey(): string {
  return dayKey(new Date())
}

/** z. B. „Mittwoch, 16. Oktober“ */
export function formatLong(date: Date): string {
  return `${WEEKDAYS[date.getDay()]}, ${date.getDate()}. ${MONTHS[date.getMonth()]}`
}

/** Kürze Wochentags-Kennung für Chart-Achsen: „Mi 16“ */
export function formatShortDay(date: Date): string {
  return `${WEEKDAYS_SHORT[date.getDay()]} ${date.getDate()}`
}

/** z. B. „10. – 16. Oktober“ bzw. „28. September – 4. Oktober“ */
export function formatRange(from: Date, to: Date): string {
  const fromMonth = MONTHS[from.getMonth()]
  const toMonth = MONTHS[to.getMonth()]
  if (fromMonth === toMonth) {
    return `${from.getDate()}. – ${to.getDate()}. ${fromMonth}`
  }
  return `${from.getDate()}. ${fromMonth} – ${to.getDate()}. ${toMonth}`
}

/** Die letzten n Tage, aufsteigend, endet bei „end“. */
export function lastNDays(n: number, end: Date = new Date()): Date[] {
  const out: Date[] = []
  for (let i = n - 1; i >= 0; i--) {
    out.push(addDays(end, -i))
  }
  return out
}

import { addDays, dayKey, parseDayKey } from './dates'

export interface Streaks {
  /** consecutive Tage bis heute (heute nicht erledigt => von gestern zurück) */
  current: number
  /** längste zusammenhängende Serie über die gesamte Geschichte */
  longest: number
}

/**
 * Rechnet Streaks aus einer Menge von Tag-Schlüsseln („JJJJ-MM-TT“).
 * Operiert auf Kalenderdaten, damit Zeitzone/UTC keine Lücken erzeugen.
 */
export function computeStreaks(dateKeys: Iterable<string>, today: Date = new Date()): Streaks {
  const set = new Set(dateKeys)
  if (set.size === 0) {
    return { current: 0, longest: 0 }
  }

  // Aktuelle Serie: heute zählt mit, sonst startet sie bei gestern.
  let cursor = new Date(today)
  if (!set.has(dayKey(cursor))) {
    cursor = addDays(cursor, -1)
  }
  let current = 0
  while (set.has(dayKey(cursor))) {
    current += 1
    cursor = addDays(cursor, -1)
  }

  // Längste Serie: ISO-Schlüssel sortieren chronologisch (Kalenderdaten).
  const sorted = [...set].sort()
  let longest = 0
  let run = 0
  let previous: Date | null = null
  for (const key of sorted) {
    const day = parseDayKey(key)
    if (previous !== null && dayKey(addDays(previous, 1)) === key) {
      run += 1
    } else {
      run = 1
    }
    longest = Math.max(longest, run)
    previous = day
  }

  return { current, longest }
}

// Datenschicht: IndexedDB über „idb“. Kein Backend – alles bleibt lokal.

import { openDB, type IDBPDatabase } from 'idb'

export type HabitColorKey = 'sage' | 'clay' | 'blue' | 'lavender' | 'sand' | 'rose'

export type MoodValue = 1 | 2 | 3 | 4 | 5

export interface Habit {
  id: string
  name: string
  emoji: string
  color: HabitColorKey
  createdAt: number
}

/** Ein Haken: Habit × Tag (Komposit-Index verhindert Doppelhaken). */
export interface Completion {
  habitId: string
  date: string
}

/** Eine Stimmung pro Tag (Schlüssel: Tag) plus optionaler Kurznotiz. */
export interface MoodEntry {
  date: string
  value: MoodValue
  note: string
}

const DB_NAME = 'rhythm'
const DB_VERSION = 1

let dbPromise: Promise<IDBPDatabase> | null = null

export function getDB(): Promise<IDBPDatabase> {
  dbPromise ??= openDB(DB_NAME, DB_VERSION, {
    upgrade(db) {
      db.createObjectStore('habits', { keyPath: 'id' })

      const completions = db.createObjectStore('completions', {
        keyPath: ['habitId', 'date'],
      })
      completions.createIndex('byHabit', 'habitId')

      db.createObjectStore('moods', { keyPath: 'date' })
    },
  })
  return dbPromise
}

// ---------- Habits ----------

export async function getAllHabits(): Promise<Habit[]> {
  const db = await getDB()
  return (await db.getAll('habits')) as Habit[]
}

export async function putHabit(habit: Habit): Promise<void> {
  const db = await getDB()
  await db.put('habits', habit)
}

/** Löscht den Habit samt aller Haken. */
export async function deleteHabit(id: string): Promise<void> {
  const db = await getDB()
  const tx = db.transaction(['habits', 'completions'], 'readwrite')
  const rows = (await tx.objectStore('completions').index('byHabit').getAll(id)) as Completion[]
  await Promise.all(
    rows.map((row) =>
      tx.objectStore('completions').delete([row.habitId, row.date] as [string, string]),
    ),
  )
  await tx.objectStore('habits').delete(id)
  await tx.done
}

// ---------- Haken ----------

export async function getAllCompletions(): Promise<Completion[]> {
  const db = await getDB()
  return (await db.getAll('completions')) as unknown as Completion[]
}

export async function putCompletion(completion: Completion): Promise<void> {
  const db = await getDB()
  await db.put('completions', completion)
}

export async function removeCompletion(habitId: string, date: string): Promise<void> {
  const db = await getDB()
  await db.delete('completions', [habitId, date] as [string, string])
}

// ---------- Stimmung ----------

export async function getAllMoods(): Promise<MoodEntry[]> {
  const db = await getDB()
  return (await db.getAll('moods')) as MoodEntry[]
}

export async function putMood(entry: MoodEntry): Promise<void> {
  const db = await getDB()
  await db.put('moods', entry)
}

export async function removeMood(date: string): Promise<void> {
  const db = await getDB()
  await db.delete('moods', date)
}

// ---------- Wartung ----------

/** Leert alle drei Stores. */
export async function clearAllData(): Promise<void> {
  const db = await getDB()
  const tx = db.transaction(['habits', 'completions', 'moods'], 'readwrite')
  await Promise.all([
    tx.objectStore('habits').clear(),
    tx.objectStore('completions').clear(),
    tx.objectStore('moods').clear(),
  ])
  await tx.done
}

// Dark Mode: folgt dem System, manuell übersteuerbar, Auswahl wird gespeichert.

export type ThemeMode = 'system' | 'light' | 'dark'

const STORAGE_KEY = 'rhythm.theme'

export function loadThemeMode(): ThemeMode {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    return raw === 'light' || raw === 'dark' ? raw : 'system'
  } catch {
    return 'system'
  }
}

export function saveThemeMode(mode: ThemeMode): void {
  try {
    localStorage.setItem(STORAGE_KEY, mode)
  } catch {
    /* Speicher nicht verfügbar: Auswahl gilt nur für diese Sitzung */
  }
}

export function isSystemDark(): boolean {
  return window.matchMedia('(prefers-color-scheme: dark)').matches
}

export function resolvedIsDark(mode: ThemeMode): boolean {
  return mode === 'dark' || (mode === 'system' && isSystemDark())
}

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from 'react'
import { loadThemeMode, resolvedIsDark, saveThemeMode, type ThemeMode } from './theme'

interface ThemeContextValue {
  mode: ThemeMode
  setMode: (mode: ThemeMode) => void
}

const ThemeContext = createContext<ThemeContextValue | null>(null)

const THEME_COLOR_LIGHT = '#F7F5F1'
const THEME_COLOR_DARK = '#141210'

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [mode, setModeState] = useState<ThemeMode>(loadThemeMode)

  const setMode = (next: ThemeMode) => {
    setModeState(next)
    saveThemeMode(next)
  }

  useEffect(() => {
    const apply = (dark: boolean) => {
      document.documentElement.classList.toggle('dark', dark)
      document
        .querySelector('meta[name="theme-color"]')
        ?.setAttribute('content', dark ? THEME_COLOR_DARK : THEME_COLOR_LIGHT)
    }

    apply(resolvedIsDark(mode))

    if (mode !== 'system') {
      return
    }

    const query = window.matchMedia('(prefers-color-scheme: dark)')
    const onChange = (event: MediaQueryListEvent) => apply(event.matches)
    query.addEventListener('change', onChange)
    return () => query.removeEventListener('change', onChange)
  }, [mode])

  return <ThemeContext.Provider value={{ mode, setMode }}>{children}</ThemeContext.Provider>
}

export function useTheme(): ThemeContextValue {
  const ctx = useContext(ThemeContext)
  if (!ctx) {
    throw new Error('useTheme muss innerhalb von <ThemeProvider> verwendet werden')
  }
  return ctx
}

// Zentraler App-Zustand: lädt die drei Stores und hält sie in Sync.
// Mutations schreiben zuerst nach IndexedDB und spiegeln den Erfolg lokal.

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react'
import * as db from '../lib/db'
import type { Completion, Habit, HabitColorKey, MoodEntry, MoodValue } from '../lib/db'
import { computeStreaks, type Streaks } from '../lib/streaks'

interface AppState {
  habits: Habit[]
  completions: Completion[]
  moods: MoodEntry[]
  loaded: boolean
}

interface AppContextValue extends AppState {
  addHabit: (name: string, emoji: string, color: HabitColorKey) => Promise<void>
  updateHabit: (id: string, patch: Partial<Pick<Habit, 'name' | 'emoji' | 'color'>>) => Promise<void>
  deleteHabit: (id: string) => Promise<void>
  toggleCompletion: (habitId: string, date: string) => Promise<void>
  setMood: (date: string, value: MoodValue, note: string) => Promise<void>
  clearAllData: () => Promise<void>
  isDone: (habitId: string, date: string) => boolean
  habitStreaks: (habitId: string) => Streaks
}

const AppContext = createContext<AppContextValue | null>(null)

export function AppProvider({ children }: { children: ReactNode }) {
  const [state, setState] = useState<AppState>({
    habits: [],
    completions: [],
    moods: [],
    loaded: false,
  })

  useEffect(() => {
    let active = true
    Promise.all([db.getAllHabits(), db.getAllCompletions(), db.getAllMoods()])
      .then(([habits, completions, moods]) => {
        if (!active) return
        setState({
          habits: [...habits].sort((a, b) => a.createdAt - b.createdAt),
          completions,
          moods,
          loaded: true,
        })
      })
      .catch(() => {
        if (active) {
          setState((s) => ({ ...s, loaded: true }))
        }
      })
    return () => {
      active = false
    }
  }, [])

  const value = useMemo<AppContextValue>(
    () => ({
      ...state,

      async addHabit(name, emoji, color) {
        const habit: Habit = {
          id: crypto.randomUUID(),
          name,
          emoji,
          color,
          createdAt: Date.now(),
        }
        await db.putHabit(habit)
        setState((s) => ({ ...s, habits: [...s.habits, habit] }))
      },

      async updateHabit(id, patch) {
        setState((s) => ({
          ...s,
          habits: s.habits.map((h) => (h.id === id ? { ...h, ...patch } : h)),
        }))
        const existing = state.habits.find((h) => h.id === id)
        if (existing) {
          await db.putHabit({ ...existing, ...patch })
        }
      },

      async deleteHabit(id) {
        setState((s) => ({
          ...s,
          habits: s.habits.filter((h) => h.id !== id),
          completions: s.completions.filter((c) => c.habitId !== id),
        }))
        await db.deleteHabit(id)
      },

      async toggleCompletion(habitId, date) {
        const exists = state.completions.some((c) => c.habitId === habitId && c.date === date)
        if (exists) {
          await db.removeCompletion(habitId, date)
        } else {
          await db.putCompletion({ habitId, date })
        }
        setState((s) => ({
          ...s,
          completions: exists
            ? s.completions.filter((c) => !(c.habitId === habitId && c.date === date))
            : [...s.completions, { habitId, date }],
        }))
      },

      async setMood(date, value, note) {
        const entry: MoodEntry = { date, value, note }
        await db.putMood(entry)
        setState((s) => ({
          ...s,
          moods: [...s.moods.filter((m) => m.date !== date), entry],
        }))
      },

      async clearAllData() {
        setState((s) => ({ ...s, habits: [], completions: [], moods: [] }))
        await db.clearAllData()
      },

      isDone: (habitId, date) =>
        state.completions.some((c) => c.habitId === habitId && c.date === date),

      habitStreaks: (habitId) =>
        computeStreaks(
          state.completions.filter((c) => c.habitId === habitId).map((c) => c.date),
        ),
    }),
    [state],
  )

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

export function useApp(): AppContextValue {
  const ctx = useContext(AppContext)
  if (!ctx) {
    throw new Error('useApp muss innerhalb von <AppProvider> verwendet werden')
  }
  return ctx
}

