import { useState } from 'react'
import { todayKey } from '../lib/dates'
import type { MoodValue } from '../lib/db'
import { MOODS } from '../lib/palette'
import { useApp } from '../state/AppProvider'

/** Stimmung des Tages: 1–5 per Tap, optional Kurznotiz. */
export function MoodCard() {
  const { moods, setMood } = useApp()
  const today = todayKey()
  const entry = moods.find((m) => m.date === today)
  const [draftNote, setDraftNote] = useState(entry?.note ?? '')

  const pick = (value: MoodValue) => {
    void setMood(today, value, draftNote.trim())
  }

  const commitNote = () => {
    if (entry) {
      void setMood(today, entry.value, draftNote.trim())
    }
  }

  return (
    <section className="rounded-2xl border border-line bg-surface p-5" aria-label="Stimmung">
      <header className="flex items-baseline justify-between">
        <h2 className="text-xs font-semibold uppercase tracking-[0.08em] text-ink-soft">
          Stimmung
        </h2>
        {entry && (
          <span className="text-xs text-ink-faint">
            <span aria-hidden="true">{MOODS[entry.value - 1].emoji}</span> {MOODS[entry.value - 1].label}
          </span>
        )}
      </header>

      <div className="mt-4 grid grid-cols-5 gap-2">
        {MOODS.map((mood) => {
          const selected = entry?.value === mood.value
          return (
            <button
              key={mood.value}
              type="button"
              aria-pressed={selected}
              aria-label={`Stimmung ${mood.value} von 5: ${mood.label}`}
              onClick={() => pick(mood.value)}
              className={`flex h-12 items-center justify-center rounded-xl border text-2xl transition-colors ${
                selected ? 'border-line bg-sunken' : 'border-transparent'
              }`}
            >
              <span aria-hidden="true">{mood.emoji}</span>
            </button>
          )
        })}
      </div>

      <input
        value={draftNote}
        onChange={(event) => setDraftNote(event.target.value)}
        onBlur={commitNote}
        onKeyDown={(event) => {
          if (event.key === 'Enter') {
            commitNote()
            event.currentTarget.blur()
          }
        }}
        placeholder="Kurznotiz (optional)"
        aria-label="Kurznotiz zur heutigen Stimmung"
        maxLength={120}
        className="mt-4 h-11 w-full rounded-lg border border-line bg-sunken/60 px-3.5 text-sm text-ink placeholder:text-ink-faint"
      />
    </section>
  )
}

import { useState, type CSSProperties } from 'react'
import { HabitForm } from '../components/HabitForm'
import { EmptyState } from '../components/EmptyState'
import { HabitRow } from '../components/HabitRow'
import { IconPlus, IconPulse } from '../components/Icon'
import { MoodCard } from '../components/MoodCard'
import { Sheet } from '../components/Sheet'
import { formatLong, todayKey } from '../lib/dates'
import type { Habit, HabitColorKey } from '../lib/db'
import { useApp } from '../state/AppProvider'

type FormState = { mode: 'new' } | { mode: 'edit'; habit: Habit } | null

/** Heute-Screen: Datum, Fortschritt, Stimmung, Habits mit Streaks. */
export function TodayScreen() {
  const app = useApp()
  const [form, setForm] = useState<FormState>(null)

  const today = todayKey()
  const habits = app.habits
  const total = habits.length
  const doneCount = habits.filter((habit) => app.isDone(habit.id, today)).length
  const progress = total === 0 ? 0 : doneCount / total

  const submit = async (name: string, emoji: string, color: HabitColorKey) => {
    if (form?.mode === 'edit') {
      await app.updateHabit(form.habit.id, { name, emoji, color })
    } else {
      await app.addHabit(name, emoji, color)
    }
    setForm(null)
  }

  return (
    <div>
      <p className="text-sm text-ink-faint">{formatLong(new Date())}</p>
      <h1 className="mt-1 font-serif text-[34px] leading-[1.08] tracking-[-0.02em]">Heute</h1>

      {total > 0 && (
        <section
          className="reveal mt-6 rounded-2xl border border-line bg-surface p-5"
          style={{ '--i': 0 } as CSSProperties}
        >
          <div className="flex items-baseline justify-between">
            <h2 className="text-xs font-semibold uppercase tracking-[0.08em] text-ink-soft">
              Fortschritt
            </h2>
            <p className="font-serif text-2xl">
              <span className="tabular-nums">{doneCount}</span>{' '}
              <span className="text-base text-ink-faint">von {total}</span>
            </p>
          </div>
          <div
            className="mt-3 h-1.5 overflow-hidden rounded-full bg-sunken"
            role="progressbar"
            aria-valuenow={doneCount}
            aria-valuemin={0}
            aria-valuemax={total}
            aria-label="Fortschritt heute"
          >
            <div
              className="bar-fill h-full w-full origin-left rounded-full bg-accent"
              style={{ transform: `scaleX(${progress})` }}
            />
          </div>
          {doneCount === total && (
            <p className="mt-3 text-sm text-accent">Alles erledigt. Ruhiger Abschluss.</p>
          )}
        </section>
      )}

      <div className="reveal mt-5" style={{ '--i': 1 } as CSSProperties}>
        <MoodCard key={today} />
      </div>

      {total > 0 ? (
        <>
          <h2 className="mt-6 px-1 text-xs font-semibold uppercase tracking-[0.08em] text-ink-soft">
            Habits
          </h2>
          <ul className="mt-2 space-y-2.5">
            {habits.map((habit, index) => (
              <HabitRow
                key={habit.id}
                habit={habit}
                done={app.isDone(habit.id, today)}
                streaks={app.habitStreaks(habit.id)}
                index={index + 2}
                onToggle={() => void app.toggleCompletion(habit.id, today)}
                onEdit={() => setForm({ mode: 'edit', habit })}
              />
            ))}
          </ul>
          <button
            type="button"
            onClick={() => setForm({ mode: 'new' })}
            className="mt-4 flex h-12 w-full items-center justify-center gap-2 rounded-lg bg-ink text-sm font-semibold text-paper transition-transform active:scale-[0.99]"
          >
            <IconPlus className="h-4 w-4" />
            Habit anlegen
          </button>
        </>
      ) : (
        <EmptyState
          icon={<IconPulse className="h-6 w-6" />}
          title="Noch keine Habits"
          body="Lege deinen ersten Habit an. Jeder Haken baust du in eine Serie – Rhythm erinnert sich an alles, auch offline."
          action={
            <button
              type="button"
              onClick={() => setForm({ mode: 'new' })}
              className="mt-5 flex h-12 items-center gap-2 rounded-lg bg-ink px-5 text-sm font-semibold text-paper transition-transform active:scale-[0.99]"
            >
              <IconPlus className="h-4 w-4" />
              Ersten Habit anlegen
            </button>
          }
        />
      )}

      {form && (
        <Sheet
          title={form.mode === 'edit' ? 'Habit bearbeiten' : 'Neuer Habit'}
          onClose={() => setForm(null)}
        >
          <HabitForm
            initial={form.mode === 'edit' ? form.habit : null}
            onSubmit={(name, emoji, color) => void submit(name, emoji, color)}
          />
        </Sheet>
      )}
    </div>
  )
}

import { useMemo, type CSSProperties } from 'react'
import {
  Bar,
  CartesianGrid,
  ComposedChart,
  Line,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts'
import { EmptyState } from '../components/EmptyState'
import { IconWeek } from '../components/Icon'
import {
  dayKey,
  formatRange,
  formatShortDay,
  lastNDays,
  parseDayKey,
  todayKey,
  formatLong,
} from '../lib/dates'
import { moodByValue } from '../lib/palette'
import { useApp } from '../state/AppProvider'

interface WeekPoint {
  key: string
  label: string
  done: number
  total: number
  mood: number | null
  note: string
  isToday: boolean
}

function WeekTooltip(props: { active?: boolean; payload?: Array<{ payload: WeekPoint }> }) {
  const { active, payload } = props
  if (!active || !payload || payload.length === 0) return null
  const point = payload[0].payload
  const mood = point.mood !== null ? moodByValue(point.mood) : undefined
  return (
    <div className="rounded-lg border border-line bg-surface px-3 py-2 text-xs shadow-lift">
      <p className="font-semibold text-ink">{formatLong(parseDayKey(point.key))}</p>
      <p className="mt-1 text-ink-soft">
        {point.done} von {point.total} Habits
      </p>
      <p className="text-ink-soft">
        {mood ? `Stimmung: ${mood.label}` : 'Keine Stimmung erfasst'}
      </p>
      {point.note && <p className="mt-1 max-w-[180px] text-ink-faint">„{point.note}“</p>}
    </div>
  )
}

/** Woche-Screen: Chart der letzten 7 Tage (Haken + Stimmung) plus Kennzahlen. */
export function WeekScreen() {
  const app = useApp()
  const habitIds = useMemo(() => new Set(app.habits.map((habit) => habit.id)), [app.habits])

  const days = useMemo(() => lastNDays(7), [])

  const data = useMemo<WeekPoint[]>(() => {
    const today = todayKey()
    return days.map((day) => {
      const key = dayKey(day)
      const done = app.completions.filter(
        (c) => c.date === key && habitIds.has(c.habitId),
      ).length
      const mood = app.moods.find((m) => m.date === key)
      return {
        key,
        label: formatShortDay(day),
        done,
        total: app.habits.length,
        mood: mood ? mood.value : null,
        note: mood?.note ?? '',
        isToday: key === today,
      }
    })
  }, [app.completions, app.moods, app.habits, habitIds, days])

  const hasData = data.some((point) => point.done > 0 || point.mood !== null)
  const moodValues = data.filter((point) => point.mood !== null).map((point) => point.mood as number)
  const avgMood = moodValues.length
    ? moodValues.reduce((sum, value) => sum + value, 0) / moodValues.length
    : null
  const totalDone = data.reduce((sum, point) => sum + point.done, 0)
  const maxDone = Math.max(3, ...data.map((point) => point.done))

  return (
    <div>
      <p className="text-sm text-ink-faint">{formatRange(days[0], days[6])}</p>
      <h1 className="mt-1 font-serif text-[34px] leading-[1.08] tracking-[-0.02em]">Woche</h1>

      {hasData ? (
        <section
          className="reveal mt-6 rounded-2xl border border-line bg-surface p-5"
          style={{ '--i': 0 } as CSSProperties}
        >
          <div className="flex items-baseline justify-between">
            <h2 className="text-xs font-semibold uppercase tracking-[0.08em] text-ink-soft">
              Letzte 7 Tage
            </h2>
            <span className="text-xs tabular-nums text-ink-faint">
              {formatRange(days[0], days[6])}
            </span>
          </div>

          <div className="mt-4 h-[210px]">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={data} margin={{ top: 8, right: 8, bottom: 0, left: 8 }}>
                <CartesianGrid vertical={false} stroke="var(--line)" strokeDasharray="3 6" />
                <XAxis
                  dataKey="label"
                  interval={0}
                  tickLine={false}
                  axisLine={false}
                  tick={{ fontSize: 11, fill: 'var(--ink-faint)' }}
                  dy={8}
                />
                <YAxis yAxisId="habits" hide domain={[0, maxDone]} allowDecimals={false} />
                <YAxis
                  yAxisId="mood"
                  orientation="right"
                  domain={[0, 5]}
                  ticks={[1, 2, 3, 4, 5]}
                  tickLine={false}
                  axisLine={false}
                  width={18}
                  tick={{ fontSize: 10, fill: 'var(--ink-faint)' }}
                />
                <Tooltip cursor={{ fill: 'var(--sunken)', opacity: 0.6 }} content={<WeekTooltip />} />
                <Bar yAxisId="habits" dataKey="done" fill="var(--accent)" radius={6} maxBarSize={18} />
                <Line
                  yAxisId="mood"
                  type="monotone"
                  dataKey="mood"
                  stroke="var(--chart-mood)"
                  strokeWidth={2}
                  connectNulls={false}
                  dot={{ r: 3, fill: 'var(--chart-mood)', strokeWidth: 0 }}
                  activeDot={{ r: 4.5, fill: 'var(--chart-mood)' }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>

          <div className="mt-3 flex items-center gap-4 text-[11px] text-ink-faint">
            <span className="flex items-center gap-1.5">
              <span className="h-2.5 w-2.5 rounded-[3px] bg-accent" aria-hidden="true" />
              Erledigte Habits
            </span>
            <span className="flex items-center gap-1.5">
              <span
                className="h-0.5 w-4 rounded-full"
                style={{ backgroundColor: 'var(--chart-mood)' }}
                aria-hidden="true"
              />
              Stimmung
            </span>
          </div>
        </section>
      ) : (
        <EmptyState
          icon={<IconWeek className="h-6 w-6" />}
          title="Noch keine Daten diese Woche"
          body="Haken ab und Stimmung notieren – hier erscheint dann dein Verlaufschart."
        />
      )}

      {hasData && (
        <div className="mt-5 grid grid-cols-2 gap-2.5">
          <section
            className="reveal rounded-2xl border border-line bg-surface p-4"
            style={{ '--i': 1 } as CSSProperties}
          >
            <p className="text-xs font-semibold uppercase tracking-[0.08em] text-ink-soft">
              Ø Stimmung
            </p>
            <p className="mt-1.5 font-serif text-[26px] leading-none">
              {avgMood !== null ? avgMood.toFixed(1) : '–'}
              <span className="ml-1 font-sans text-sm text-ink-faint">/ 5</span>
            </p>
          </section>
          <section
            className="reveal rounded-2xl border border-line bg-surface p-4"
            style={{ '--i': 2 } as CSSProperties}
          >
            <p className="text-xs font-semibold uppercase tracking-[0.08em] text-ink-soft">
              Erledigt
            </p>
            <p className="mt-1.5 font-serif text-[26px] leading-none">
              {totalDone}
              <span className="ml-1 font-sans text-sm text-ink-faint">Haken</span>
            </p>
          </section>
        </div>
      )}
    </div>
  )
}

import { useState, type CSSProperties } from 'react'
import { HabitForm } from '../components/HabitForm'
import { IconMoon, IconMonitor, IconPencil, IconPlus, IconSun, IconTrash } from '../components/Icon'
import { Segmented } from '../components/Segmented'
import { Sheet } from '../components/Sheet'
import { habitColorVar } from '../lib/palette'
import type { Habit } from '../lib/db'
import { useApp } from '../state/AppProvider'
import { useTheme } from '../theme/ThemeProvider'

type SettingsForm = { habit: Habit | 'new' } | null

/** Einstellungen: Farbschema, Habit-Verwaltung, Daten, Info. */
export function SettingsScreen() {
  const app = useApp()
  const { mode, setMode } = useTheme()
  const [form, setForm] = useState<SettingsForm>(null)
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null)
  const [confirmClear, setConfirmClear] = useState(false)

  // Zweistufige Bestätigung: erst tippen, dann „Wirklich?“ – ohne systemeigene Dialoge.
  const startDelete = (id: string) => {
    if (confirmDeleteId === id) {
      void app.deleteHabit(id)
      setConfirmDeleteId(null)
    } else {
      setConfirmDeleteId(id)
      window.setTimeout(() => {
        setConfirmDeleteId((current) => (current === id ? null : current))
      }, 3500)
    }
  }

  const startClear = () => {
    if (confirmClear) {
      void app.clearAllData()
      setConfirmClear(false)
    } else {
      setConfirmClear(true)
      window.setTimeout(() => setConfirmClear(false), 3500)
    }
  }

  const submit = async (name: string, emoji: string, color: Habit['color']) => {
    if (form?.habit === 'new') {
      await app.addHabit(name, emoji, color)
    } else if (form?.habit) {
      await app.updateHabit(form.habit.id, { name, emoji, color })
    }
    setForm(null)
  }

  return (
    <div>
      <h1 className="font-serif text-[34px] leading-[1.08] tracking-[-0.02em]">Einstellungen</h1>

      <section className="mt-6 rounded-2xl border border-line bg-surface p-5">
        <h2 className="text-xs font-semibold uppercase tracking-[0.08em] text-ink-soft">
          Erscheinung
        </h2>
        <div className="mt-3">
          <Segmented
            label="Farbschema"
            value={mode}
            onChange={setMode}
            options={[
              { value: 'system', label: 'System', icon: <IconMonitor className="h-4 w-4" /> },
              { value: 'light', label: 'Hell', icon: <IconSun className="h-4 w-4" /> },
              { value: 'dark', label: 'Dunkel', icon: <IconMoon className="h-4 w-4" /> },
            ]}
          />
        </div>
        <p className="mt-3 text-xs leading-relaxed text-ink-faint">
          Folgt standardmäßig deiner Systemeinstellung. Die Auswahl bleibt auf diesem Gerät
          gespeichert.
        </p>
      </section>

      <section className="mt-5">
        <div className="flex items-center justify-between px-1">
          <h2 className="text-xs font-semibold uppercase tracking-[0.08em] text-ink-soft">
            Habits
          </h2>
          <button
            type="button"
            onClick={() => setForm({ habit: 'new' })}
            className="flex h-11 items-center gap-1 rounded-lg px-2 text-sm font-medium text-accent"
          >
            <IconPlus className="h-4 w-4" />
            Anlegen
          </button>
        </div>

        {app.habits.length > 0 ? (
          <ul className="mt-2 space-y-2">
            {app.habits.map((habit, index) => {
              const streaks = app.habitStreaks(habit.id)
              const confirming = confirmDeleteId === habit.id
              return (
                <li
                  key={habit.id}
                  className="reveal flex min-h-[60px] items-center gap-2.5 rounded-2xl border border-line bg-surface p-2.5"
                  style={{ '--i': index } as CSSProperties}
                >
                  <span
                    className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-xl"
                    style={{
                      backgroundColor: `color-mix(in oklab, ${habitColorVar(habit.color)} 14%, transparent)`,
                    }}
                    aria-hidden="true"
                  >
                    {habit.emoji}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-[15px] font-medium text-ink">{habit.name}</p>
                    <p className="mt-0.5 text-xs tabular-nums text-ink-faint">
                      Serie {streaks.current} · Rekord {streaks.longest}
                    </p>
                  </div>
                  <button
                    type="button"
                    onClick={() => setForm({ habit })}
                    aria-label={`„${habit.name}“ bearbeiten`}
                    className="flex h-11 w-11 shrink-0 items-center justify-center rounded-lg text-ink-soft"
                  >
                    <IconPencil className="h-4 w-4" />
                  </button>
                  <button
                    type="button"
                    onClick={() => startDelete(habit.id)}
                    aria-label={
                      confirming
                        ? 'Löschen bestätigen'
                        : `„${habit.name}“ endgültig löschen`
                    }
                    className={`flex h-11 shrink-0 items-center justify-center gap-1.5 rounded-lg text-xs font-semibold transition-colors ${
                      confirming ? 'bg-danger-soft px-3 text-danger' : 'w-11 text-ink-faint'
                    }`}
                  >
                    <IconTrash className="h-4 w-4" />
                    {confirming && 'Wirklich?'}
                  </button>
                </li>
              )
            })}
          </ul>
        ) : (
          <p className="mt-2 rounded-2xl border border-line bg-surface/60 p-4 text-sm text-ink-soft">
            Noch keine Habits angelegt.
          </p>
        )}
      </section>

      <section className="mt-5 rounded-2xl border border-line bg-surface p-5">
        <h2 className="text-xs font-semibold uppercase tracking-[0.08em] text-ink-soft">Daten</h2>
        <p className="mt-3 text-xs leading-relaxed text-ink-faint">
          Habits, Haken und Stimmungen liegen ausschließlich lokal in IndexedDB auf diesem Gerät.
          Kein Account, keine Cloud, keine Synchronisation.
        </p>
        <button
          type="button"
          onClick={startClear}
          className={`mt-4 flex h-12 w-full items-center justify-center gap-2 rounded-lg border text-sm font-semibold transition-colors ${
            confirmClear
              ? 'border-danger bg-danger-soft text-danger'
              : 'border-line text-ink-soft'
          }`}
        >
          <IconTrash className="h-4 w-4" />
          {confirmClear ? 'Wirklich alles löschen?' : 'Alle Daten löschen'}
        </button>
      </section>

      <div className="mt-6 flex items-center justify-between px-1 pb-2">
        <p className="text-xs text-ink-faint">Rhythm 1.0</p>
        <p className="text-xs text-ink-faint">lokal · offline · privat</p>
      </div>

      {form && (
        <Sheet
          title={form.habit === 'new' ? 'Neuer Habit' : 'Habit bearbeiten'}
          onClose={() => setForm(null)}
        >
          <HabitForm
            initial={form.habit === 'new' ? null : form.habit}
            onSubmit={(name, emoji, color) => void submit(name, emoji, color)}
          />
        </Sheet>
      )}
    </div>
  )
}

import { useState } from 'react'
import { BottomNav, type Tab } from './components/BottomNav'
import { AppProvider, useApp } from './state/AppProvider'
import { SettingsScreen } from './screens/SettingsScreen'
import { ThemeProvider } from './theme/ThemeProvider'
import { TodayScreen } from './screens/TodayScreen'
import { WeekScreen } from './screens/WeekScreen'

export default function App() {
  return (
    <ThemeProvider>
      <AppProvider>
        <Shell />
      </AppProvider>
    </ThemeProvider>
  )
}

function Shell() {
  const [tab, setTab] = useState<Tab>('heute')
  const { loaded } = useApp()

  return (
    <div className="min-h-dvh bg-paper text-ink">
      <main className="mx-auto w-full max-w-[440px] px-5 pt-8 pb-32">
        {!loaded ? (
          <div className="flex h-64 items-center justify-center text-sm text-ink-faint">
            Lädt …
          </div>
        ) : (
          <div key={tab} className="fade-swap">
            {tab === 'heute' && <TodayScreen />}
            {tab === 'woche' && <WeekScreen />}
            {tab === 'einstellungen' && <SettingsScreen />}
          </div>
        )}
      </main>
      <BottomNav tab={tab} onChange={setTab} />
    </div>
  )
}

