// WCAG-Kontrastberechnung für die Rhythm-Farbpaare (Light + Dark).
// Rein informativ: gibt die echten Kontrastverhältnisse für den Jev-Check aus.

function lum(hex) {
  const n = parseInt(hex.slice(1), 16)
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => {
    const c = v / 255
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)
  })
  return 0.2126 * r + 0.7152 * g + 0.0722 * b
}

function ratio(a, b) {
  const [l1, l2] = [lum(a), lum(b)].sort((x, y) => y - x)
  return (l1 + 0.05) / (l2 + 0.05)
}

// color-mix(in oklab, C 13%, transparent) über Surface approximieren:
// oklab-Mix mit transparent ≈ alpha-Blending in sRGB für diese Werte (genau genug)
function mix13(fg, bg) {
  const f = parseInt(fg.slice(1), 16)
  const b = parseInt(bg.slice(1), 16)
  const out = []
  for (let i = 0; i < 3; i++) {
    const fv = (f >> (16 - 8 * i)) & 255
    const bv = (b >> (16 - 8 * i)) & 255
    out.push(Math.round(0.13 * fv + 0.87 * bv))
  }
  return '#' + out.map((v) => v.toString(16).padStart(2, '0')).join('')
}

const L = {
  paper: '#f7f5f1', surface: '#ffffff', ink: '#17150f', inkSoft: '#5b564b',
  inkFaint: '#8d877a', accent: '#5b7157', chartMood: '#a4705a', danger: '#9f2f2d',
  habit: { sage: '#55684c', clay: '#8a5a44', blue: '#4f688a', lavender: '#665a7e', sand: '#8a7444', rose: '#8a5560' },
  habitCheck: '#ffffff',
}
const D = {
  paper: '#141210', surface: '#1c1a17', ink: '#f1eee7', inkSoft: '#a8a294',
  inkFaint: '#7d786c', accent: '#9dae8e', chartMood: '#c89a83', danger: '#d8a19c',
  habit: { sage: '#a3b595', clay: '#c89a83', blue: '#96acc9', lavender: '#ac9cc8', sand: '#c4ac7b', rose: '#c595a0' },
  habitCheck: '#17150f',
}

const rows = []
const add = (mode, pair, f, b, need) =>
  rows.push(`${mode} | ${pair} | ${f} auf ${b} | ${ratio(f, b).toFixed(2)}:1 | nötig ${need}`)

for (const [mode, t] of [['light', L], ['dark', D]]) {
  add(mode, 'Text/Haupt', t.ink, t.paper, '4.5:1')
  add(mode, 'Text/Soft', t.inkSoft, t.surface, '4.5:1')
  add(mode, 'Text/Faint', t.inkFaint, t.surface, '4.5:1')
  add(mode, 'Akzent/Fläche', t.accent, t.surface, '3:1')
  add(mode, 'Button-Text', t.paper === '#f7f5f1' ? L.paper : D.paper, t.ink, '4.5:1')
  add(mode, 'Danger/Fläche', t.danger, t.surface, '4.5:1')
  add(mode, 'Chart-Linie (Grafik)', t.chartMood, t.surface, '3:1')
  for (const [name, c] of Object.entries(t.habit)) {
    add(mode, `Habit-${name} Chip-Text`, c, mix13(c, t.surface), '4.5:1')
    add(mode, `Habit-${name} Haken-Haken (Grafik)`, t.habitCheck, c, '3:1')
  }
}

console.log(rows.join('\n'))

