// WCAG-Kontrastberechnung für die Rhythm-Farbpaare (Light + Dark).
// Liest alle Werte direkt aus src/index.css.

import { readFileSync } from 'node:fs'

const css = readFileSync(
  '/Users/cedi/Clouds/Projekte/KI/LLM-Bench/tests/habit-tracker/Qwen3.8-27B-4bit-Splash/src/index.css',
  'utf8',
)

function blockOf(selector) {
  const re = new RegExp(selector.replace(/\\/g, '\\\\') + '\\s*\\{[\\s\\S]*?\\n\\}')
  const m = css.match(re)
  if (!m) throw new Error('Block nicht gefunden: ' + selector)
  return m[0]
}

function varIn(block, name) {
  const m = block.match(new RegExp('--' + name + ':\\s*(#[0-9a-fA-F]{6})'))
  if (!m) throw new Error('Variable --' + name + ' nicht gefunden')
  return m[1]
}

const lightBlock = blockOf(':root')
const darkBlock = blockOf('\\.dark')

function readTheme(block) {
  return {
    paper: varIn(block, 'paper'),
    surface: varIn(block, 'surface'),
    ink: varIn(block, 'ink'),
    inkSoft: varIn(block, 'ink-soft'),
    inkFaint: varIn(block, 'ink-faint'),
    accent: varIn(block, 'accent'),
    chartMood: varIn(block, 'chart-mood'),
    danger: varIn(block, 'danger'),
    habitCheck: varIn(block, 'habit-check'),
    habit: {
      sage: varIn(block, 'habit-sage'),
      clay: varIn(block, 'habit-clay'),
      blue: varIn(block, 'habit-blue'),
      lavender: varIn(block, 'habit-lavender'),
      sand: varIn(block, 'habit-sand'),
      rose: varIn(block, 'habit-rose'),
    },
  }
}

const L = readTheme(lightBlock)
const D = readTheme(darkBlock)

function lum(hex) {
  const n = parseInt(hex.slice(1), 16)
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => {
    const c = v / 255
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)
  })
  return 0.2126 * r + 0.7152 * g + 0.0722 * b
}

function ratio(a, b) {
  const [l1, l2] = [lum(a), lum(b)].sort((x, y) => y - x)
  return (l1 + 0.05) / (l2 + 0.05)
}

// color-mix(in oklab, C 13%, transparent) über Surface approximieren
// (oklab-Mix mit transparent ≈ sRGB-Alpha-Blending; Genauigkeit reicht für die Prüfung)
function mix13(fg, bg) {
  const f = parseInt(fg.slice(1), 16)
  const b = parseInt(bg.slice(1), 16)
  const out = []
  for (let i = 0; i < 3; i++) {
    const fv = (f >> (16 - 8 * i)) & 255
    const bv = (b >> (16 - 8 * i)) & 255
    out.push(Math.round(0.13 * fv + 0.87 * bv))
  }
  return '#' + out.map((v) => v.toString(16).padStart(2, '0')).join('')
}

const rows = []
const add = (mode, pair, fg, bg, need) =>
  rows.push(`${mode} | ${pair} | ${fg} auf ${bg} | ${ratio(fg, bg).toFixed(2)}:1 | nötig ${need}`)

for (const [mode, t] of [['light', L], ['dark', D]]) {
  add(mode, 'Text/Haupt', t.ink, t.paper, '4.5:1')
  add(mode, 'Text/Soft', t.inkSoft, t.surface, '4.5:1')
  add(mode, 'Text/Faint', t.inkFaint, t.surface, '4.5:1')
  add(mode, 'Akzent/Fläche', t.accent, t.surface, '3:1')
  add(mode, 'Button-Text (Tinten-Button)', t.paper, t.ink, '4.5:1')
  add(mode, 'Danger/Fläche', t.danger, t.surface, '4.5:1')
  add(mode, 'Chart-Linie (Grafik)', t.chartMood, t.surface, '3:1')
  for (const [name, c] of Object.entries(t.habit)) {
    add(mode, `Habit-${name} Chip-Text`, c, mix13(c, t.surface), '4.5:1')
    add(mode, `Habit-${name} Haken-Check (Grafik)`, t.habitCheck, c, '3:1')
  }
}

console.log(rows.join('\n'))

